package com.beeboee.magnot.region;import net.minecraft.entity.item.ItemEntity;import net.minecraft.entity.player.PlayerEntity;import net.minecraft.util.math.AxisAlignedBB;import net.minecraft.util.math.vector.Vector3d;import net.minecraft.world.server.ServerWorld;import java.util.*;public final class FerrousMagnetRules{private static final Map<String,Boolean>CACHE=new HashMap<String,Boolean>();private static long tick=Long.MIN_VALUE;private static String dim="";private FerrousMagnetRules(){}public static boolean blocksMagnet(ServerWorld l,Vector3d s,Vector3d t){prepare(l);String k=key(s,t);Boolean v=CACHE.get(k);if(v!=null)return v;boolean b=FerrousRegionSavedData.get(l).containsPoint(s)||FerrousRegionSavedData.get(l).blocksMagnet(s,t);CACHE.put(k,b);return b;}public static boolean blocksItemPull(ServerWorld l,Vector3d s,ItemEntity i){return blocksMagnet(l,s,itemTarget(i));}public static boolean blocksPlayerItemPull(ServerWorld l,PlayerEntity p,ItemEntity i){AxisAlignedBB box=p.getBoundingBox();Vector3d t=itemTarget(i);return blocksMagnet(l,p.position(),t)||blocksMagnet(l,box.getCenter(),t)||blocksMagnet(l,p.getEyePosition(1),t);}public static Vector3d itemTarget(ItemEntity i){return i.position().add(0,i.getBbHeight()*.5,0);}static void invalidateCaches(){CACHE.clear();tick=Long.MIN_VALUE;dim="";}private static void prepare(ServerWorld l){long t=l.getGameTime();String d=l.dimension().location().toString();if(t!=tick||!d.equals(dim)){CACHE.clear();tick=t;dim=d;}}private static String key(Vector3d a,Vector3d b){return bucket(a.x)+":"+bucket(a.y)+":"+bucket(a.z)+":"+bucket(b.x)+":"+bucket(b.y)+":"+bucket(b.z);}private static int bucket(double v){return(int)Math.floor(v*64);}}
